def quai_du_client(type_client):
    """Renvoie le quai d'un client : "Q1", "Q2", "Q3" ou "Q4"."""
    if type_client == "café":
        quai = "Q1"
    elif type_client == "magasin":
        quai = "Q2"
    elif type_client == "particulier":
        quai = "Q3"
    else:
        quai = "Q4"
    return quai
